import { Component, EventEmitter, Input, Output } from '@angular/core';

export type NavigationKey = 'ArrowDown' | 'ArrowUp' | 'Home' | 'End';

const navigationKeys: NavigationKey[] = ['ArrowDown', 'ArrowUp', 'Home', 'End'];

@Component({
  selector: 'app-faq-item',
  standalone: true,
  templateUrl: './faq-item.component.html',
  styleUrls: ['./faq-item.component.css']
})
export class FaqItemComponent {
  @Input() itemId = '';
  @Input() question = '';
  @Input() answer = '';
  @Input() isOpen = false;
  @Output() toggle = new EventEmitter<void>();
  @Output() navigate = new EventEmitter<NavigationKey>();

  get triggerId(): string {
    return 'faq-trigger-' + this.itemId;
  }

  get panelId(): string {
    return 'faq-panel-' + this.itemId;
  }

  onHeaderClick(): void {
    this.toggle.emit();
  }

  onHeaderKeydown(event: KeyboardEvent): void {
    const navigationKey = event.key as NavigationKey;
    if (!navigationKeys.includes(navigationKey)) return;

    event.preventDefault();
    this.navigate.emit(navigationKey);
  }
}

