import { Component } from '@angular/core';
import { FaqItemComponent, type NavigationKey } from './faq-item.component';

interface FaqItem {
  id: string;
  question: string;
  answer: string;
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [FaqItemComponent],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly faqItems: FaqItem[] = [
    {
      id: 'faq-1',
      question: 'Lorem ipsum dolor sit amet?',
      answer: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed non risus euismod, posuere justo ut, pulvinar neque.'
    },
    {
      id: 'faq-2',
      question: 'Curabitur blandit tempus porttitor?',
      answer: 'Curabitur blandit tempus porttitor. Integer posuere erat a ante venenatis dapibus posuere velit aliquet.'
    },
    {
      id: 'faq-3',
      question: 'Aenean lacinia bibendum nulla sed consectetur?',
      answer: 'Aenean lacinia bibendum nulla sed consectetur. Cras justo odio, dapibus ac facilisis in, egestas eget quam.'
    },
    {
      id: 'faq-4',
      question: 'Vivamus sagittis lacus vel augue laoreet rutrum?',
      answer: 'Vivamus sagittis lacus vel augue laoreet rutrum faucibus dolor auctor. Maecenas faucibus mollis interdum.'
    }
  ];

  allowMultiple = false;
  openItemIds: string[] = [];

  isItemOpen(itemId: string): boolean {
    return this.openItemIds.includes(itemId);
  }

  onItemToggle(itemId: string): void {
    if (this.isItemOpen(itemId)) {
      this.openItemIds = this.openItemIds.filter((openId) => openId !== itemId);
      return;
    }

    this.openItemIds = this.allowMultiple
      ? [...this.openItemIds, itemId]
      : [itemId];
  }

  onAllowMultipleChange(event: Event): void {
    const nextAllowMultiple = (event.target as HTMLInputElement).checked;
    this.allowMultiple = nextAllowMultiple;

    if (!nextAllowMultiple) {
      this.openItemIds = this.openItemIds.slice(0, 1);
    }
  }

  onItemNavigate(itemIndex: number, key: NavigationKey): void {
    let nextIndex = itemIndex;

    if (key === 'ArrowDown') {
      nextIndex = (itemIndex + 1) % this.faqItems.length;
    } else if (key === 'ArrowUp') {
      nextIndex = (itemIndex - 1 + this.faqItems.length) % this.faqItems.length;
    } else if (key === 'Home') {
      nextIndex = 0;
    } else if (key === 'End') {
      nextIndex = this.faqItems.length - 1;
    }

    const nextItem = this.faqItems[nextIndex];
    document.getElementById('faq-trigger-' + nextItem.id)?.focus();
  }
}

